inv=json.loads((p/'docs/stage9/inventory.json').read_text(encoding='utf-8'));accepted={a for item in inv['routines'] for a in item['blocks']};records=[]
specs=[(0x2838,0x2860,'Trigger pool reset',sources[0],'16freeLONGkeys6936+16*i;terminalnull,cursor0andclear6A36sentinelLONG. Preserveall16recordbytes.'),(0x2860,0x2888,'Deferred marker pool reset',sources[1],'24freeLONGkeys6AA2+10*i;terminalnull,cursor0andhead6B92zero. Recordpayloadsremainstale.'),(0x4b00,0x4b2e,'Trigger unlink and recycle',sources[0],'Readnode.nextWORD;nonnullnext.previous=node.previous. Nonnullprevious.next=node.next includingheadsentinel. Pushsignextendedrecordkeyonto currentfree-stack; returnupdatedstackaddressA1lowWORD in typedAPI. Removedrecordlinks/payloadremainstale.'),(0x4adc,0x4af4,'Trigger unlink and restore source',sources[0],'Unlink4B00then signextendnode.markerWORD12 torestore savedBYTE14. Preserveoriginalnodefields; typedwrapperhasnoA1return,matchingpreservedcontinuationAPI.'),(0x4af4,0x4b00,'Trigger consume without restore',sources[0],'Unlink4B00withoutsourcewrite. OriginalMOVEMrestoresD0/D1butA1notpreserved; typedconsume returnslowWORDfree-stackaddress forscannerlower-Xhandoff.'),(0x2b8c,0x2bce,'Saved spawn far rectangle',sources[2],'Actor116nonzerofalse. WORDwrapped referenceX-368..+688 andY-240..+464; signedinclusivebounds againstsaved94/96. Truecorresponds originalD0=-1; noactorwrites.'),(0x2bce,0x2c4c,'Actor marker restore or defer',sources[1],'ZeroLONG88skip. Signedinclusivewrapped referenceX-80..+400,Y-80..+304. Inboundsnonemptyfree-stackpopsrecord, storesoldhead/marker90/value92/XY94/96; publishhead. Outofbounds/fullpoolrestoreLONG88WORD92immediately; do notchangeactor.'),(0x2c4c,0x2cbc,'Deferred marker list update',sources[1],'Traversefiniteuniquechain; retaininclusivebounds. Removal setsD0lowWORD=node.marker, restoresWORDvalue through signextendedkey, splicespredecessor andpushesrecordkey. SubsequentlowerXusesmutatedmarkerWORD; upperXandYboundsremainoriginal. Removedpayloadsremainstale.')]
for start,end,name,source,contract in specs:
 at=start;items=[]
 while at<end:
  assert at in accepted;i=Decoder(rom,at).decode();items.append(i);at+=i['size']
 assert at==end
 records.append(dict(address=start,hex=f'{start:06X}',end_exclusive=end,original_bytes=rom[start:end].hex(),instruction_evidence=items,verification_status='verified',status='verified green: local '+name,native_sources=[source],checked_cases=r[f'{start:X}'],contract=contract,proof='Independent whole-pool/state and event oracles.256priorBYTEpatternsforreset; finite triggerlistslength1..16,16rotations,everyremovalposition andall3releaseAPIs inclsourceimagepreservation. All65536referenceWORDs x8 signed/wrap/edgepartitions forbounds/restoration; emptydeferredheadorfullstackinitialdomain. Deferredlistslength0..24 x256statuspatterns x4orders; survivor-listoracle includesliteral lowerXclobber andLIFOslotpushorder. Completeoriginalboundaries/branchespinned.',scope='Local typedpool APIs, finiteuniquevalidlinks, adequatefree-stackspace andstablemarkerpublicationcallbacks. Resettypedcursors replace originalpointerfields; rawCPUABI/malformedlinks/sourcealias/globalpublication/actualframecaller integrationremainexternal. Restore/defer insertion evidence currentlyempty-head/fullpooldomain; nativeoldheadstore reviewed butnotcompleteallocation/lifecyclecertification. Notwholelevelclaim.'))
report=dict(rom_sha256=ROM_HASH,source_sha256={s:hashlib.sha256((p/s).read_bytes()).hexdigest() for s in sources},records=records,test_executable_sha256=hashlib.sha256(exe.read_bytes()).hexdigest(),results_sha256=hashlib.sha256(rp.read_bytes()).hexdigest())
(p/'docs/stage9/marker-queues-verification.json').write_text(json.dumps(report,indent=2)+'\n',encoding='utf-8');print('Eight original marker/trigger queue contracts verified.')
